import Lean.Data.String

def implementation (a b: String) : String :=
let len := a.length;
let result := String.mk len '0';
let mut i := 0;
while i < len do
  let i_pos := String.Pos.mk i;
  let a_char := a.get i_pos;
  let b_char := b.get i_pos;
  if a_char = b_char then
    result := result.set i_pos '0'
  else
    result := result.set i_pos '1';
  i := i + 1;
result

import Lean.Data.List

def implementation (numbers: List Int) : Bool :=
let n := numbers.length
let rec check_pairs (i: Nat) : Bool :=
  if i = n then false
  else
    let j := i + 1
    if j = n then check_pairs (i + 1)
    else
      if numbers[i]! + numbers[j]! = 0 then true
      else check_pairs (j + 1)
check_pairs 0

